-- Import HamQRG: ripetitori RepeaterBook + arricchimento DMR
-- Generato da gen_import.py | source='repeaterbook-2026-09'
-- repeaters: 17541 | access: 30431
-- RICHIEDE: migration 20260908120000_add_access_modes_p25_irlp.sql gia applicata

-- NB: supabase db push esegue ogni migration dentro una transazione,
-- quindi qui NON si apre un begin/commit esplicito (sarebbe annidato
-- e il commit chiuderebbe in anticipo la transazione del CLI).

-- PostGIS in Supabase vive nello schema extensions: senza questo
-- search_path la colonna generata repeaters.geom non risolve il tipo
-- geography e l'insert fallisce (SQLSTATE 42704).
set search_path = public, extensions;

set statement_timeout = '30min';

-- guardia: P25 e IRLP devono esistere nell'enum
do $$ begin
  if not exists (select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid
                 where t.typname='access_mode' and e.enumlabel='P25')
  or not exists (select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid
                 where t.typname='access_mode' and e.enumlabel='IRLP') then
    raise exception 'access_mode manca P25/IRLP: applica prima la migration';
  end if;
end $$;

create temp table _imp_rep (
  name text, callsign text, manager text, frequency_hz bigint,
  shift_hz bigint, shift_raw text,
  region text, province_code text, locality text, locator text,
  lat double precision, lon double precision, is_active boolean,
  external_id text
);


create temp table _imp_acc (
  frequency_hz bigint, locator text, mode public.access_mode,
  ctcss_hz numeric(6,1), color_code smallint, talkgroup bigint,
  node_id integer, notes text
);


-- 1) repeaters
   region, province_code, locality, locator, lat, lon, source, is_active, external_id)
select name, callsign, manager, frequency_hz, shift_hz, shift_raw,
       region, province_code, locality, locator, lat, lon,
       'repeaterbook-2026-09', is_active, external_id
from _imp_rep
on conflict do nothing;

-- 2) access (risolve repeater_id via chiave naturale)
   tone_scope, tone_direction)
select r.id, a.mode, a.ctcss_hz, a.color_code, a.talkgroup, a.node_id, a.notes,
       'repeaterbook-2026-09',
       case when a.ctcss_hz is not null then 'local'::public.tone_scope
            else 'unknown'::public.tone_scope end,
       case when a.ctcss_hz is not null then 'tx'::public.tone_direction
            else 'unknown'::public.tone_direction end
from _imp_acc a
join public.repeaters r
  on r.frequency_hz = a.frequency_hz and r.locator = a.locator
on conflict do nothing;

drop table _imp_rep;
drop table _imp_acc;
